"use client";

import { useSubmit, useFinanceData } from "@/lib/api";
import { useState } from "react";
import { Card, Skeleton, FormModal } from "@/components/finance";
import { ACCOUNT_CATEGORIES, ACCOUNT_TYPES } from "@/components/finance/constants";
import { AccountForm, GoalForm, InsuranceForm, SalaryForm } from "@/components/finance/forms";

const SettingsPage = ({ tab = "accounts" }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [modalType, setModalType] = useState<"account" | "goal" | "insurance" | "salary">("account");

  const submit = useSubmit();
  const { data: accounts, isLoading: accountsLoading, error: accountsError } = useFinanceData("/accounts");
  const { data: goals, isLoading: goalsLoading, error: goalsError } = useFinanceData("/goals");
  const { data: insurances, isLoading: insurancesLoading, error: insurancesError } = useFinanceData("/insurance");
  const { data: salaries, isLoading: salariesLoading, error: salariesError } = useFinanceData("/salary");

  const handleModalOpen = (type: "account" | "goal" | "insurance" | "salary") => {
    setModalType(type);
    setIsModalOpen(true);
  };

  const handleModalClose = () => {
    setIsModalOpen(false);
  };

  return (
    <div className="flex flex-col gap-4">
      <Card title="Accounts" loading={accountsLoading} error={accountsError}>
        <div className="flex flex-col gap-2">
          {accounts?.map((account) => (
            <div key={account.id} className="flex justify-between items-center">
              <div>{account.name}</div>
              <button onClick={() => handleModalOpen("account")}>Manage</button>
            </div>
          ))}
          <button onClick={() => handleModalOpen("account")}>+ Add Account</button>
        </div>
      </Card>
      <Card title="Goals" loading={goalsLoading} error={goalsError}>
        <div className="flex flex-col gap-2">
          {goals?.map((goal) => (
            <div key={goal.id} className="flex justify-between items-center">
              <div>{goal.name}</div>
              <button onClick={() => handleModalOpen("goal")}>Manage</button>
            </div>
          ))}
          <button onClick={() => handleModalOpen("goal")}>+ Add Goal</button>
        </div>
      </Card>
      <Card title="Insurance" loading={insurancesLoading} error={insurancesError}>
        <div className="flex flex-col gap-2">
          {insurances?.map((insurance) => (
            <div key={insurance.id} className="flex justify-between items-center">
              <div>{insurance.name}</div>
              <button onClick={() => handleModalOpen("insurance")}>Manage</button>
            </div>
          ))}
          <button onClick={() => handleModalOpen("insurance")}>+ Add Insurance</button>
        </div>
      </Card>
      <Card title="Salary" loading={salariesLoading} error={salariesError}>
        <div className="flex flex-col gap-2">
          {salaries?.map((salary) => (
            <div key={salary.id} className="flex justify-between items-center">
              <div>{salary.name}</div>
              <button onClick={() => handleModalOpen("salary")}>Manage</button>
            </div>
          ))}
          <button onClick={() => handleModalOpen("salary")}>+ Add Salary</button>
        </div>
      </Card>
      {isModalOpen && (
        <FormModal onClose={handleModalClose}>
          {modalType === "account" && <AccountForm onSubmit={submit} />}
          {modalType === "goal" && <GoalForm onSubmit={submit} />}
          {modalType === "insurance" && <InsuranceForm onSubmit={submit} />}
          {modalType === "salary" && <SalaryForm onSubmit={submit} />}
        </FormModal>
      )}
    </div>
  );
};

export default SettingsPage;
